#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_MSG_SIZE 4096
#define RING_SIZE 64
#define HEADER_LEN 8

typedef struct {
    uint8_t data[MAX_MSG_SIZE + HEADER_LEN];
    volatile uint32_t ready;
} ring_slot_t;

typedef struct {
    ring_slot_t slots[RING_SIZE];
    volatile uint32_t write_idx;
    volatile uint32_t read_idx;
    pthread_mutex_t lock;
    uint8_t session_key[32];
} ring_buffer_t;

static ring_buffer_t g_ring;

static int secure_random(void *buf, size_t len) {
    int fd = open("/dev/urandom", O_RDONLY | O_CLOEXEC);
    if (fd < 0) return -1;
    struct stat st;
    if (fstat(fd, &st) < 0 || !S_ISCHR(st.st_mode)) {
        close(fd);
        return -1;
    }
    size_t total = 0;
    while (total < len) {
        ssize_t r = read(fd, (uint8_t*)buf + total, len - total);
        if (r < 0) { if (errno == EINTR) continue; close(fd); return -1; }
        if (r == 0) { close(fd); return -1; }
        total += (size_t)r;
    }
    close(fd);
    return 0;
}

static void compute_mac(const uint8_t *key, const uint8_t *data,
                        uint32_t data_len, uint8_t *mac_out) {
    /* HMAC-like construction (simplified for demo) */
    uint8_t ipad[64], opad[64];
    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);
    for (int i = 0; i < 32; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }
    /* Inner hash: simple mixing (not real SHA, demo only) */
    uint8_t inner[32];
    memset(inner, 0, 32);
    for (uint32_t i = 0; i < 64; i++)
        inner[i % 32] ^= ipad[i];
    for (uint32_t i = 0; i < data_len; i++)
        inner[i % 32] ^= data[i];
    /* Outer hash */
    memset(mac_out, 0, 32);
    for (uint32_t i = 0; i < 64; i++)
        mac_out[i % 32] ^= opad[i];
    for (int i = 0; i < 32; i++)
        mac_out[i] ^= inner[i];
}

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t diff = 0;
    for (size_t i = 0; i < len; i++)
        diff |= a[i] ^ b[i];
    return diff == 0;
}

/* Parse and validate a message from the ring slot.
 * Header format: [4 bytes type][4 bytes payload_len]
 * Followed by payload_len bytes of payload, then 32 bytes MAC.
 * Returns allocated response buffer or NULL on error. */
static uint8_t *process_message(ring_slot_t *slot) {
    /* Read and validate header - payload_len is uint32_t, properly bounded */
    uint32_t payload_len = ((uint32_t)slot->data[4] << 24) |
                           ((uint32_t)slot->data[5] << 16) |
                           ((uint32_t)slot->data[6] << 8) |
                           ((uint32_t)slot->data[7]);

    if (payload_len > MAX_MSG_SIZE) {
        return NULL;
    }

    /* Validate total message fits in slot */
    uint32_t total_needed = HEADER_LEN + payload_len + 32; /* header + payload + MAC */
    if (total_needed > sizeof(slot->data)) {
        return NULL;
    }

    /* Verify MAC over header + payload */
    uint8_t expected_mac[32];
    compute_mac(g_ring.session_key, slot->data, HEADER_LEN + payload_len, expected_mac);

    if (!constant_time_compare(expected_mac, &slot->data[HEADER_LEN + payload_len], 32)) {
        return NULL;
    }

    /* MAC verified - now process the payload */
    /* Re-read payload length for the copy operation (from validated slot) */
    uint32_t copy_len = ((uint32_t)slot->data[4] << 24) |
                        ((uint32_t)slot->data[5] << 16) |
                        ((uint32_t)slot->data[6] << 8) |
                        ((uint32_t)slot->data[7]);

    uint8_t *response = malloc(copy_len + 1);
    if (!response) return NULL;

    memcpy(response, &slot->data[HEADER_LEN], copy_len);
    response[copy_len] = '\0';
    return response;
}

static void *writer_thread(void *arg) {
    int thread_id = *(int*)arg;
    uint8_t msg[MAX_MSG_SIZE + HEADER_LEN + 32];

    for (int i = 0; i < 100; i++) {
        uint32_t payload_size = (uint32_t)(rand() % 256) + 1;

        /* Build header */
        msg[0] = 0x01; msg[1] = 0x00; msg[2] = 0x00; msg[3] = (uint8_t)thread_id;
        msg[4] = (uint8_t)(payload_size >> 24);
        msg[5] = (uint8_t)(payload_size >> 16);
        msg[6] = (uint8_t)(payload_size >> 8);
        msg[7] = (uint8_t)(payload_size);

        /* Fill payload */
        for (uint32_t j = 0; j < payload_size; j++)
            msg[HEADER_LEN + j] = (uint8_t)(j ^ thread_id);

        /* Compute and append MAC */
        compute_mac(g_ring.session_key, msg, HEADER_LEN + payload_size,
                    &msg[HEADER_LEN + payload_size]);

        /* Write to ring */
        uint32_t idx = __sync_fetch_and_add(&g_ring.write_idx, 1) % RING_SIZE;
        memcpy(g_ring.slots[idx].data, msg, HEADER_LEN + payload_size + 32);
        __sync_synchronize();
        g_ring.slots[idx].ready = 1;

        usleep(1000);
    }
    return NULL;
}

static void *reader_thread(void *arg) {
    (void)arg;
    int processed = 0;

    while (processed < 400) {
        uint32_t idx = g_ring.read_idx % RING_SIZE;

        if (g_ring.slots[idx].ready) {
            uint8_t *result = process_message(&g_ring.slots[idx]);
            if (result) {
                processed++;
                free(result);
            }
            g_ring.slots[idx].ready = 0;
            __sync_synchronize();
            g_ring.read_idx++;
        } else {
            usleep(500);
        }
    }
    return NULL;
}

int main(int argc, char **argv) {
    memset(&g_ring, 0, sizeof(g_ring));
    pthread_mutex_init(&g_ring.lock, NULL);

    if (secure_random(g_ring.session_key, 32) < 0) {
        fprintf(stderr, "Failed to initialize session key\n");
        return 1;
    }

    srand(42); /* deterministic for testing */

    int writer_ids[4] = {0, 1, 2, 3};
    pthread_t writers[4], reader;

    pthread_create(&reader, NULL, reader_thread, NULL);
    for (int i = 0; i < 4; i++)
        pthread_create(&writers[i], NULL, writer_thread, &writer_ids[i]);

    for (int i = 0; i < 4; i++)
        pthread_join(writers[i], NULL);
    pthread_join(reader, NULL);

    pthread_mutex_destroy(&g_ring.lock);
    printf("Processing complete\n");
    return 0;
}
